      signature,
      summary,
      details,
      source,
      params: [],
      returns: kind === "method" || kind === "function" ? "See the exact signature and status/result contract." : "",
      ownership: "References are intrusive owning handles unless the signature or detailed contract states that they are borrowed.",
      errors: kind === "method" || kind === "function" ? "Unsupported capabilities and invalid arguments are reported through FArdaRHIStatus or TArdaRHIResult." : "",
